-- Period study v2; read-only; 2026-09-05 through 2026-09-11 Asia/Shanghai.
-- Observation frame uses ended lessons in the available daily partitions.
-- See report for snapshot, completeness and denominator limitations.
WITH frame AS (SELECT school_uid,COUNT(1) AS scheduled_n,SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END) AS opened_n,SUM(CASE WHEN class_status=4 THEN 1 ELSE 0 END) AS cancelled_n FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND school_uid>0 GROUP BY school_uid HAVING SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END)>0), thresholds AS (SELECT percentile_approx(opened_n,0.3333333333) AS q1,percentile_approx(opened_n,0.6666666667) AS q2 FROM frame), strat AS (SELECT f.school_uid,f.scheduled_n,f.opened_n,f.cancelled_n,CASE WHEN f.opened_n<=t.q1 THEN 'low' WHEN f.opened_n<=t.q2 THEN 'mid' ELSE 'high' END AS stratum,t.q1,t.q2 FROM frame f CROSS JOIN thresholds t), per_pair AS (SELECT e.biz_type,e.action,e.school_uid,e.course_id,e.activity_id,e.uid,COUNT(1) AS n FROM eo_pdviews.dwd_acitive_user_lms_action_details_di_view e JOIN strat f ON e.school_uid=f.school_uid WHERE e.dt>='2026-09-05' AND e.dt<='2026-09-11' AND e.event_time>=1788537600 AND e.event_time<1789142400 AND e.role='student' AND e.action IN ('handin_homework','handin_exam') GROUP BY e.biz_type,e.action,e.school_uid,e.course_id,e.activity_id,e.uid) SELECT biz_type,action,SUM(n) AS event_n,COUNT(1) AS student_activity_n,SUM(CASE WHEN n>1 THEN 1 ELSE 0 END) AS repeated_pair_n,SUM(CASE WHEN uid IS NULL OR activity_id IS NULL OR school_uid IS NULL OR course_id IS NULL THEN 1 ELSE 0 END) AS null_key_pairs FROM per_pair GROUP BY biz_type,action ORDER BY biz_type,action LIMIT 10;
